from http.server import BaseHTTPRequestHandler, HTTPServer
import json, ssl

class H(BaseHTTPRequestHandler):
    def do_POST(self):
        n = int(self.headers.get('Content-Length', 0))
        req = self.rfile.read(n)
        open('req.bin','ab').write(req + b'\n---\n')   # 留证据
        # 按抓包还原的字段结构返回
        body = json.dumps({
            "code": 0,
            "data": {
                "license": {"status": "valid", "expire": "2099-12-31",
                            "type": "enterprise", "seats": 999},
                "sign": "[用真实签名算法重算，见下]"
            }
        }).encode()
        self.send_response(200)
        self.send_header('Content-Type','application/json')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

srv = HTTPServer(('0.0.0.0', 443), H)
ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
ctx.load_cert_chain('fake.crt', 'fake.key')   # 自签即可，客户端已 pin 就先走路径 C
srv.socket = ctx.wrap_socket(srv.socket, server_side=True)
srv.serve_forever()
