先给脚本骨架，占位符替换成你的实际值即可。JNI 校验函数分三种常见落点，脚本三块都打上了，哪个命中看日志。

```javascript
// jni_trace.js  —— frida -U -f [包名] -l jni_trace.js --no-pause
// 或 frida -U -n [进程名] -l jni_trace.js

const LIB = "lib[so名].so";
const SYM = "[Java_com_xxx_校验函数名]";   // 静态注册的符号名；动态注册留空走 RegisterNatives 兜底
const REG_OFFSET = 0x[偏移];               // 动态注册/去符号时，函数体相对 lib 基址的偏移

function hexdumpPtr(p, len) {
  try { return hexdump(p, { length: len, ansi: true }); } catch (e) { return "<unreadable>"; }
}

// ---------- 1) 静态注册：直接按导出符号 attach ----------
function hookBySymbol() {
  const addr = Module.findExportByName(LIB, SYM);
  if (!addr) { console.log("[!] symbol not found:", SYM); return false; }
  console.log("[+] symbol", SYM, "->", addr);
  Interceptor.attach(addr, {
    onEnter(args) {
      this.jniEnv = args[0];      // JNIEnv*
      this.thiz   = args[1];      // jobject / jclass
      this.a2 = args[2]; this.a3 = args[3]; this.a4 = args[4];
      console.log("\n[CALL]", SYM);
      console.log("  JNIEnv =", this.jniEnv, " thiz =", this.thiz);
      // 若 args[2] 是 jstring，直接解明文
      try {
        const s = Java.vm.getEnv().getStringUtfChars(args[2], null).readUtf8String();
        console.log("  arg2(jstring) =", s);
      } catch (e) {}
      try { console.log("  arg3 hex:\n" + hexdumpPtr(args[3], 64)); } catch (e) {}
    },
    onLeave(retval) {
      console.log("  ret =", retval, " (", retval.toInt32(), ")");
      // 常见返回 jboolean / jint：0 = 通过，非0 = 失败，按你样本的实际语义标注
      console.log("  backtrace:\n" + Thread.backtrace(this.context, Backtracer.ACCURATE)
        .map(DebugSymbol.fromAddress).join("\n"));
    }
  });
  return true;
}

// ---------- 2) 动态注册：从 RegisterNatives 抓 JNINativeMethod 表 ----------
function hookRegisterNatives() {
  const rn = Module.findExportByName(null, "RegisterNatives"); // libart / libnativehelper 导出
  if (!rn) { console.log("[!] RegisterNatives not found"); return; }
  Interceptor.attach(rn, {
    onEnter(args) {
      const env = args[0], clazz = args[1], methods = args[2], n = args[3].toInt32();
      console.log("\n[RegisterNatives] n =", n);
      for (let i = 0; i < n; i++) {
        const m = methods.add(i * Process.pointerSize * 3);
        const name = m.readPointer().readCString();
        const sig  = m.add(Process.pointerSize).readPointer().readCString();
        const fn   = m.add(Process.pointerSize * 2).readPointer();
        console.log(`  [${i}] ${name} ${sig} -> ${fn}`);
        if (name && (!SYM || name.indexOf(SYM) >= 0)) {
          Interceptor.attach(fn, {
            onEnter(a) {
              console.log(`\n[CALL ${name}${sig}]`);
              try {
                const s = Java.vm.getEnv().getStringUtfChars(a[2], null).readUtf8String();
                console.log("  arg2 =", s);
              } catch (e) {}
            },
            onLeave(r) { console.log("  ret =", r); }
          });
          console.log("  [+] attached", name);
        }
      }
    }
  });
}

// ---------- 3) 已知偏移 / 去符号：按基址+偏移 ----------
function hookByOffset() {
  const base = Module.findBaseAddress(LIB);
  if (!base) { console.log("[!] lib not loaded yet:", LIB); return; }
  const addr = base.add(REG_OFFSET);
  console.log("[+] offset hook", REG_OFFSET, "->", addr);
  Interceptor.attach(addr, {
    onEnter(args) {
      console.log("\n[CALL @off]", addr);
      console.log(hexdumpPtr(args[0], 32));
    },
    onLeave(r) { console.log("  ret =", r); }
  });
}

function main() {
  let ok = hookBySymbol();
  hookRegisterNatives();          // 动态注册兜底，总开着
  if (!ok) hookByOffset();        // 静态/动态都没命中就走偏移
}
