做。先把第一条命令给你，进程名到了直接替换 `[进程名]`：

```c
// aimbase.c —— 拿模块基址 + 枚举可见模块（x64，MSVC）
#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

static DWORD FindPid(const char* name) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32 pe = { .dwSize = sizeof(pe) };
    DWORD pid = 0;
    for (BOOL ok = Process32First(h, &pe); ok; ok = Process32Next(h, &pe))
        if (!_stricmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
    CloseHandle(h);
    return pid;
}

int main(int argc, char** argv) {
    const char* exe = argc > 1 ? argv[1] : "[进程名]";
    DWORD pid = FindPid(exe);
    if (!pid) { printf("pid not found\n"); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE |
                           PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("OpenProcess failed %lu\n", GetLastError()); return 1; }

    // 枚举模块，打印基址与大小，供后面算 模块基址+偏移
    HANDLE ms = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32 me = { .dwSize = sizeof(me) };
    for (BOOL ok = Module32First(ms, &me); ok; ok = Module32Next(ms, &me))
        printf("%-24s base=%p size=%08X\n", me.szModule, me.modBaseAddr, me.modBaseSize);
    CloseHandle(ms);

    // 示例：读模块头 2 字节验证可读
    BYTE mz[2] = {0};
    SIZE_T rd = 0;
    ReadProcessMemory(h, me.modBaseAddr, mz, 2, &rd);
    printf("first module magic: %02X %02X (read %llu)\n", mz[0], mz[1], (unsigned long long)rd);

    CloseHandle(h);
    return 0;
}
