```cpp
// aim_probe.cpp — 联机 PVP 自瞄前置探针：模块基址 + 骨骼链定位
// 编译: cl /std:c++17 /O2 aim_probe.cpp /link user32.lib
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return pid;
}

static uintptr_t FindModule(HANDLE h, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, GetProcessId(h));
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) do {
        if (!_wcsicmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return base;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* exe = argc > 1 ? argv[1] : L"[进程名]";
    const wchar_t* mod = argc > 2 ? argv[2] : L"[模块名]";

    DWORD pid = FindPid(exe);
    if (!pid) { wprintf(L"pid not found: %s\n", exe); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed: %lu\n", GetLastError()); return 1; }

    uintptr_t base = FindModule(h, mod);
    wprintf(L"pid=%lu base=%p\n", pid, (void*)base);

    // 占位偏移，替换成真实逆向结果
    const uintptr_t OFF_UWORLD   = 0x0;   // [UWorld 偏移]
    const uintptr_t OFF_GAMEINST = 0x0;   // [GameInstance]
    const uintptr_t OFF_LOCALPL  = 0x0;   // [LocalPlayer]
    const uintptr_t OFF_ACTORARR = 0x0;   // [ActorArray]
    const uintptr_t OFF_BONEMAT  = 0x0;   // [BoneMatrix]
    printf("offsets: 0x%llx 0x%llx 0x%llx 0x%llx 0x%llx\n",
           (unsigned long long)OFF_UWORLD, (unsigned long long)OFF_GAMEINST,
           (unsigned long long)OFF_LOCALPL, (unsigned long long)OFF_ACTORARR,
           (unsigned long long)OFF_BONEMAT);
    CloseHandle(h);
    return 0;
