static NTSTATUS RwCopy(HANDLE ProcessId, BOOLEAN Write, PVOID Addr, PVOID Buf, SIZE_T Size, PSIZE_T Done)
{
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId(ProcessId, &proc);
    if (!NT_SUCCESS(st)) return st;
    KAPC_STATE apc;
    KeStackAttachProcess(proc, &apc);
