```cpp
// ace_probe.cpp — 探测 ACE 对目标进程的句柄保护
#include <windows.h>
#include <cstdio>

int wmain(int argc, wchar_t** argv) {
    if (argc < 2) { wprintf(L"usage: ace_probe.exe <pid>\n"); return 1; }
    DWORD pid = (DWORD)_wtoi(argv[1]);
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) {
        wprintf(L"OpenProcess failed: %lu\n", GetLastError());
        return 2;
    }
    // 读基址
    HMODULE mods[1024]; DWORD need = 0;
    if (EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        wchar_t name[MAX_PATH];
        for (DWORD i = 0; i < need / sizeof(HMODULE); i++) {
            GetModuleBaseNameW(h, mods[i], name, MAX_PATH);
            wprintf(L"%p  %s\n", mods[i], name);
            if (!_wcsicmp(name, L"Game.exe") || !_wcsicmp(name, L"[模块名]"))
                wprintf(L"  ^^^ 目标主模块基址 = 0x%p\n", mods[i]);
        }
    } else {
        wprintf(L"EnumProcessModulesEx failed: %lu (句柄被剥权限)\n", GetLastError());
    }
    // 尝试读一个字节 —— 判断 VM_READ 是否真被拦
    if (mods[0]) {
        BYTE b = 0; SIZE_T r = 0;
        if (ReadProcessMemory(h, mods[0], &b, 1, &r))
            wprintf(L"RPM ok, first byte = 0x%02X\n", b);
        else
            wprintf(L"RPM failed: %lu (ACE 剥了 PROCESS_VM_READ)\n", GetLastError());
    }
    return 0;
}
```

