Java.perform(function () {});

function hookIl2cpp() {
  const mod = Process.findModuleByName("libil2cpp.so");
  if (!mod) { console.log("libil2cpp not loaded"); return; }
  console.log("libil2cpp base =", mod.base);

  // IL2CPP 导出：il2cpp_domain_get / il2cpp_class_from_name / il2cpp_field_get_offset
  const il2cpp_domain_get = new NativeFunction(mod.findExportByName("il2cpp_domain_get"), "pointer", []);
  const il2cpp_domain_get_assemblies = new NativeFunction(
    mod.findExportByName("il2cpp_domain_get_assemblies"), "pointer", ["pointer", "pointer"]);
  const il2cpp_assembly_get_image = new NativeFunction(
    mod.findExportByName("il2cpp_assembly_get_image"), "pointer", ["pointer"]);
  const il2cpp_class_from_name = new NativeFunction(
    mod.findExportByName("il2cpp_class_from_name"), "pointer",
    ["pointer", "pointer", "pointer"]);
  const il2cpp_class_get_field_from_name = new NativeFunction(
    mod.findExportByName("il2cpp_class_get_field_from_name"), "pointer",
    ["pointer", "pointer"]);
  const il2cpp_field_get_offset = new NativeFunction(
    mod.findExportByName("il2cpp_field_get_offset"), "size_t", ["pointer"]);

  const domain = il2cpp_domain_get();
  const sizePtr = Memory.alloc(4);
  const asms = il2cpp_domain_get_assemblies(domain, sizePtr);
  const cnt = sizePtr.readU32();
  let targetClass = null;
  for (let i = 0; i < cnt; i++) {
    const img = il2cpp_assembly_get_image(asms.add(i * 8).readPointer());
    const cls = il2cpp_class_from_name(img, Memory.allocUtf8String("PlayerData"),
                                      Memory.allocUtf8String("GameData"));
    if (!cls.isNull()) { targetClass = cls; break; }
  }
  if (!targetClass) { console.log("class not found"); return; }
  const field = il2cpp_class_get_field_from_name(targetClass,
                Memory.allocUtf8String("[金币字段名]"));
  if (!field.isNull()) {
    console.log("gold field offset = 0x" + il2cpp_field_get_offset(field).toString(16));
  }
}
hookIl2cpp();
