int main(void) {
    // 1) 进程枚举通道：CreateToolhelp32Snapshot 能看到自己吗
    HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe = { .dwSize = sizeof(pe) };
    DWORD myPid = GetCurrentProcessId();
    if (Process32FirstW(hSnap, &pe)) {
        do {
            if (pe.th32ProcessID == myPid)
                wprintf(L"[TOOLHELP] self visible: pid=%lu name=%s\n", pe.th32ProcessID, pe.szExeFile);
        } while (Process32NextW(hSnap, &pe));
    }
    CloseHandle(hSnap);

    // 2) 窗口枚举通道：反作弊常用 GetForegroundWindow + GetWindowThreadProcessId
    HWND fg = GetForegroundWindow();
    DWORD wndPid = 0;
    if (fg) { GetWindowThreadProcessId(fg, &wndPid); }
    wprintf(L"[WINDOW] foreground pid=%lu (self=%lu)\n", wndPid, myPid);

    // 3) 模块枚举通道：EnumProcessModulesEx 是否暴露你的 DLL
    HMODULE mods[256]; DWORD need = 0;
    HANDLE hSelf = GetCurrentProcess();
    if (EnumProcessModulesEx(hSelf, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        for (DWORD i = 0; i < need / sizeof(HMODULE); i++) {
            wchar_t path[MAX_PATH] = {0};
            GetModuleFileNameExW(hSelf, mods[i], path, MAX_PATH);
            wprintf(L"[MODULE] %s\n", path);
        }
    }
    // 4) 句柄权限基线：谁能 OpenProcess 你，取决于 DACL + ObRegisterCallbacks 回调
    return 0;
