    if (clip[3] < 0.01f) return false;
    float inv = 1.0f / clip[3];
    s.x = (ww * 0.5f) + (clip[0] * inv * ww * 0.5f);
    s.y = (wh * 0.5f) - (clip[1] * inv * wh * 0.5f);
    return true;
}
