// probe.cpp — 目标进程枚举 + 模块基址 + 反作弊驱动探测
// cl probe.cpp /std:c++17 /EHsc
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdio>
#include <string>

#pragma comment(lib, "psapi.lib")

static const wchar_t* TARGET = L"[进程名].exe";   // ← 填目标

int wmain() {
    // 1. 提权到 SeDebugPrivilege
    HANDLE hTok; OpenProcessToken(GetCurrentProcess(), TOKEN_ADJUST_PRIVILEGES, &hTok);
    TOKEN_PRIVILEGES tp{}; tp.PrivilegeCount = 1;
    LookupPrivilegeValueW(nullptr, SE_DEBUG_NAME, &tp.Privileges[0].Luid);
    tp.Privileges[0].Attributes = SE_PRIVILEGE_ENABLED;
    AdjustTokenPrivileges(hTok, FALSE, &tp, 0, nullptr, nullptr);

    // 2. 找进程
    DWORD pid = 0;
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
        if (!_wcsicmp(pe.szExeFile, TARGET)) { pid = pe.th32ProcessID; break; }
    CloseHandle(snap);
    if (!pid) { wprintf(L"[-] 进程未找到: %s\n", TARGET); return 1; }
    wprintf(L"[+] PID = %lu\n", pid);

    // 3. 打开进程（完整权限，反作弊会拦，先看拦不拦）
    HANDLE h = OpenProcess(PROCESS_ALL_ACCESS, FALSE, pid);
    if (!h) { wprintf(L"[-] OpenProcess 失败, GetLastError=%lu (可能被 ObRegisterCallbacks 剥权限)\n",
                      GetLastError()); h = OpenProcess(
                      PROCESS_VM_READ|PROCESS_VM_WRITE|PROCESS_QUERY_INFORMATION, FALSE, pid); }
    if (!h) { wprintf(L"[-] 降权也失败 -> 走内核态读写\n"); return 2; }
    wprintf(L"[+] OpenProcess OK, handle=%p\n", h);

    // 4. 模块枚举 + 基址
    HMODULE mods[1024]; DWORD need = 0;
    if (!EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_ALL)) return 3;
    DWORD n = need / sizeof(HMODULE);
    for (DWORD i = 0; i < n; ++i) {
        wchar_t name[MAX_PATH]{};
        GetModuleBaseNameW(h, mods[i], name, MAX_PATH);
        MODULEINFO mi{};
        GetModuleInformation(h, mods[i], &mi, sizeof(mi));
        wprintf(L"  %-32s base=%p size=0x%08X\n", name,
                (void*)mi.lpBaseOfDll, mi.SizeOfImage);
    }

    // 5. 反作弊驱动 / 服务探测（ACE/BattlEye/EAC/TP/Vanguard 等）
    wprintf(L"\n[*] 内核驱动与服务:\n");
    system("sc query type= driver state= all | findstr /i \"ace base bl eac tp vgk gameguard xigncode anti\"");
    system("driverquery /v | findstr /i \"ace base bl eac tp vgk\"");
    system("fltmc filters");
    return 0;
}
