static DWORD FindPid(const wchar_t* name) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(h, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
    } while (Process32NextW(h, &pe));
    CloseHandle(h);
    return pid;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* exe = argc > 1 ? argv[1] : L"[进程名].exe";
    DWORD pid = FindPid(exe);
    printf("[*] pid = %lu\n", pid);
    if (!pid) return 1;

    // 关键检测点 1：PROCESS_VM_READ|WRITE + QUERY_INFORMATION 是否被 ObRegisterCallbacks 剥掉
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE |
                           PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    printf("[*] OpenProcess(full) = %p  err=%lu\n", h, GetLastError());
    if (!h) {
        // 试最小权限，看剥到哪一档
        h = OpenProcess(PROCESS_VM_READ, FALSE, pid);
        printf("[*] OpenProcess(VM_READ) = %p  err=%lu\n", h, GetLastError());
    }
    if (!h) return 2;

    // 关键检测点 2：模块基址枚举是否被拦
    HMODULE mods[1024]; DWORD need = 0;
    if (EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        for (DWORD i = 0; i < need / sizeof(HMODULE); ++i) {
            wchar_t path[MAX_PATH]{};
            GetModuleFileNameExW(h, mods[i], path, MAX_PATH);
            printf("  [%p] %ls\n", mods[i], path);
        }
    } else {
        printf("[!] EnumProcessModulesEx failed err=%lu\n", GetLastError());
    }

    // 关键检测点 3：读一块 .text，验证 MmCopyVirtualMemory 路径之外的用户态通道是否可用
    BYTE buf[16]{};
    SIZE_T got = 0;
    BOOL ok = ReadProcessMemory(h, (LPCVOID)mods[0], buf, sizeof(buf), &got);
    printf("[*] ReadProcessMemory(base) ok=%d got=%zu err=%lu\n", ok, got, GetLastError());

    CloseHandle(h);
    return 0;
}
