BattlEye 剥的是**句柄权限**，所以用户态 `OpenProcess` 会挂。走内核 `MmCopyVirtualMemory`：

```c
// readwrite.c — WDM 驱动核心读写，占位符 [目标PID] [源地址] [目标地址]
#include <ntifs.h>

NTSTATUS ReadProcessMemoryInternal(
    HANDLE pid, PVOID src, PVOID dst, SIZE_T size, PSIZE_T bytes)
{
    PEPROCESS process = NULL;
    NTSTATUS status = PsLookupProcessByProcessId(pid, &process);
    if (!NT_SUCCESS(status)) return status;

    KAPC_STATE apc;
    KeStackAttachProcess(process, &apc);
    __try {
        ProbeForRead(src, size, 1);
        memcpy(dst, src, size);
        *bytes = size;
        status = STATUS_SUCCESS;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        status = GetExceptionCode();
    }
    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(process);
    return status;
}

NTSTATUS WriteProcessMemoryInternal(
    HANDLE pid, PVOID dst, PVOID src, SIZE_T size, PSIZE_T bytes)
{
    PEPROCESS process = NULL;
    NTSTATUS status = PsLookupProcessByProcessId(pid, &process);
    if (!NT_SUCCESS(status)) return status;

    KAPC_STATE apc;
    KeStackAttachProcess(process, &apc);
    __try {
        ProbeForWrite(dst, size, 1);
        memcpy(dst, src, size);
        *bytes = size;
        status = STATUS_SUCCESS;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        status = GetExceptionCode();
    }
    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(process);
    return status;
}
