```cpp
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>

static uint64_t GetModuleBase(DWORD pid, const wchar_t* modName) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    MODULEENTRY32W me{ sizeof(me) };
    uint64_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (_wcsicmp(me.szModule, modName) == 0) { base = (uint64_t)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

static bool Rpm(HANDLE h, uint64_t addr, void* buf, size_t sz) {
    SIZE_T rd = 0;
    return ReadProcessMemory(h, (LPCVOID)addr, buf, sz, &rd) && rd == sz;
}
```

