#define CR3RW_IOCTL_READ_PHYS     CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define CR3RW_IOCTL_WRITE_PHYS    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define CR3RW_IOCTL_READ_VIRT     CTL_CODE(FILE_DEVICE_UNKNOWN, 0x803, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define CR3RW_IOCTL_WRITE_VIRT    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x804, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define CR3RW_IOCTL_GET_MODBASE   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x805, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _CR3RW_REQ {
    ULONG     Pid;          // 目标进程 ID
    ULONGLONG Cr3;          // 目标 CR3（物理地址）
    ULONGLONG Va;           // 虚拟地址
    ULONGLONG Pa;           // 物理地址
    ULONG     Size;
    ULONG     Status;       // 驱动回填
    UCHAR     Data[1];      // 变长载荷
} CR3RW_REQ, *PCR3RW_REQ;
```

