```cpp
// dmpx64.cpp — cl /std:c++17 /EHsc dmpx64.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static ULONGLONG ModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    ULONGLONG base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (!_wcsicmp(me.szModule, mod)) { base = (ULONGLONG)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = argc > 1 ? argv[1] : L"[进程名]";
    const wchar_t* mod  = argc > 2 ? argv[2] : L"[模块名]";
    const ULONGLONG off = argc > 3 ? wcstoull(argv[3], nullptr, 16) : 0x[偏移];
    const SIZE_T    len = argc > 4 ? (SIZE_T)wcstoull(argv[4], nullptr, 16) : 0x40;

    DWORD pid = FindPid(proc);
    if (!pid) { wprintf(L"pid not found: %ls\n", proc); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed: %lu\n", GetLastError()); return 2; }

    ULONGLONG base = ModuleBase(pid, mod);
    if (!base) { wprintf(L"module not found: %ls\n", mod); CloseHandle(h); return 3; }

    ULONGLONG addr = base + off;
    std::vector<BYTE> buf(len);
    SIZE_T got = 0;
    if (!ReadProcessMemory(h, (LPCVOID)addr, buf.data(), len, &got)) {
        wprintf(L"RPM failed at 0x%llX: %lu\n", addr, GetLastError());
        CloseHandle(h); return 4;
    }

    wprintf(L"pid=%lu base=%ls+0x%llX addr=0x%llX got=%zu\n", pid, mod, off, addr, got);
    for (SIZE_T i = 0; i < got; i += 16) {
        wprintf(L"%016llX  ", addr + i);
        for (SIZE_T j = 0; j < 16 && i + j < got; ++j) wprintf(L"%02X ", buf[i + j]);
        wprintf(L"\n");
    }
    CloseHandle(h);
    return 0;
}
```

