// aimbot_core.cpp — 先编这个，验证「能读到敌人坐标」
#include <windows.h>
#include <TlHelp32.h>
#include <cmath>
#include <vector>
#include <cstdio>

// ===== 占位符：换成你逆向出来的真实值 =====
#define PROC_NAME   L"[进程名].exe"          // 例如 L"game.exe"
#define MOD_NAME    "[模块名]"               // 例如 "GameAssembly.dll" / "client.dll"
#define OFF_GWORLD  [GWorld偏移]             // UWorld / GWorld 指针偏移
#define OFF_ULEVEL  0x[ULevel偏移]
#define OFF_ACTORS  0x[Actors数组偏移]
#define OFF_ACTOR_COUNT 0x[Count偏移]
#define OFF_ROOTCOMP    0x[RootComponent偏移]
#define OFF_REL_LOC     0x[RelativeLocation偏移]  // FVector 三 float
#define OFF_CAMERA      0x[Camera偏移]
#define OFF_FOV         0x[FOV偏移]
// =========================================

uintptr_t g_base = 0;
HANDLE    g_proc = nullptr;

uintptr_t GetModuleBase(DWORD pid, const char* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    MODULEENTRY32 me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32First(snap, &me)) {
        do {
            if (_stricmp(me.szModule, mod) == 0) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32Next(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

template<class T> T RPM(uintptr_t addr) {
    T v{};
    ReadProcessMemory(g_proc, (LPCVOID)addr, &v, sizeof(T), nullptr);
    return v;
}

struct Vec3 { float x, y, z; };

// 遍历世界里的 Actor 列表，挑出带 RootComponent 的实体
std::vector<uintptr_t> GetActors() {
    std::vector<uintptr_t> out;
    uintptr_t gworld = RPM<uintptr_t>(g_base + OFF_GWORLD);
    if (!gworld) return out;
    uintptr_t ulevel = RPM<uintptr_t>(gworld + OFF_ULEVEL);
    if (!ulevel) return out;
    uintptr_t arr = RPM<uintptr_t>(ulevel + OFF_ACTORS);
    int count     = RPM<int>(ulevel + OFF_ACTOR_COUNT);
    if (!arr || count <= 0 || count > 10000) return out;
    std::vector<uintptr_t> buf(count);
    ReadProcessMemory(g_proc, (LPCVOID)arr, buf.data(), count * sizeof(uintptr_t), nullptr);
    for (auto a : buf) if (a) out.push_back(a);
    return out;
}

Vec3 GetActorLocation(uintptr_t actor) {
    uintptr_t root = RPM<uintptr_t>(actor + OFF_ROOTCOMP);
    if (!root) return {};
    return RPM<Vec3>(root + OFF_REL_LOC);
}
```

